def f(g):
    # demo: 1-column input Hx1 -> output 3H x 2: each cell becomes 1x2 [v v], stacked in pattern:
    # rows 0..H-1: reverse order of input (bottom to top)
    # rows H..2H-1: original order
    # rows 2H..3H-1: reversed again
    h=len(g); out=[]
    def row(v): return [v,v]
    for r in g[::-1]: out.append(row(r[0]))
    for r in g: out.append(row(r[0]))
    for r in g[::-1]: out.append(row(r[0]))
    return out
